import React from 'react';
import Slider from 'react-slick';
import './index.css';

const images = [
  "data:image/jpeg;base64,",
   "data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRPwWiYE2yzknKSCD4h0Nee52Q8k4c2kBNd-Q&s"
];

const ImageCarousel = () => {
  const settings = {
    dots: false,
    infinite: true,
    speed: 500,
    slidesToShow: 3,
    slidesToScroll: 1,
    arrows: true,
    responsive: [
      {
        breakpoint: 768,
        settings: { slidesToShow: 2 }
      },
      {
        breakpoint: 480,
        settings: { slidesToShow: 1 }
      }
    ]
  };

  return (
    <div className="image-carousel">
      <Slider {...settings}>
        {images.map((img, idx) => (
          <div key={idx} className="image-slide">
            <img src={img} alt={`Slide ${idx + 1}`} />
          </div>
        ))}
      </Slider>
    </div>
  );
};

export default ImageCarousel;
